  'vault.how.eyebrow': 'HOW THIS WORKS',
  'vault.how.title': 'Why the Vault exists — and how to use it',
  'vault.how.intro': 'The Vault is MotoPass’s Seal pillar. Every material program claim should carry a Bitcoin birth certificate. This page lets you audit those proofs yourself — no brochure trust required.',
  'vault.how.step1.title': 'What gets stamped',
  'vault.how.step1.body': 'Flagship program snapshots — costs, legal extracts, pathway notes — are hashed and anchored to Bitcoin via OpenTimestamps. Satohash.io provides human-readable verification receipts with block height.',
  'vault.how.step2.title': 'Verified vs demo anchors',
  'vault.how.step2.body': 'Verified proofs have real Satohash URLs and optional .ots files on disk. Demo anchors are seed placeholders — useful for UI testing but not independent chain proof. Filter chips let you see each lane clearly.',
  'vault.how.step3.title': 'Verify in your browser',
  'vault.how.step3.body': 'Paste a SHA-256 content hash, upload a matching .ots file, or click “Use this proof” on any program card. MotoPass validates format locally and links you to Satohash for independent verification.',
  'vault.how.step4.title': 'Share proof lineage',
  'vault.how.step4.body': 'Copy a Nostr kind:30078 event stub to broadcast program updates on your relay. Pair with Apply to stamp your own application hash — the same pipeline operators use for diligence.',
  'vault.how.footer': 'Educational only — not legal, tax, or investment advice. MotoPass does not custody documents; you verify independently on Bitcoin.',
  'distressed.how.eyebrow': 'HOW THIS WORKS',
  'distressed.how.title': 'Why Distressed exists — and how deals flow',
  'distressed.how.intro': 'Distressed is MotoPass’s Forge pillar — a proof-gated marketplace for sovereign plays that are undervalued, capital-efficient, or structurally interesting. Not a listings site. Every row requires Satohash proof before it appears.',
  'distressed.how.step1.title': 'How listings are built',
  'distressed.how.step1.body': 'Only flagship-depth programs with pathways and Satohash proofs qualify. Each listing shows one pathway, a ₿-first ask, red flags, and optimization tips pulled from live countries.json — not static marketing copy.',
  'distressed.how.step2.title': 'Curated vs permissionless',
  'distressed.how.step2.body': 'Curated lane: top-scoring plays hand-picked by Kimi for operator fit. Permissionless lane: same proof gate, but buyer beware — MotoPass coordinates intelligence, not custody. Both lanes require proof_url.',
  'distressed.how.step3.title': 'Reading the distressed score',
  'distressed.how.step3.body': 'Score 1–5 ranks capital efficiency and value signals — lower minimums, solvency routes, budget keywords, and sovereignty trade-offs. Filter by region, min score, and max ask to narrow your stack candidates.',
  'distressed.how.step4.title': 'From listing to deal room',
  'distressed.how.step4.body': 'Open a card → verify proof in Vault → review the escrow template (PSBT stub, no fund custody) → Apply or escalate to a Kimi agent in the deal room. MotoPass never holds your Bitcoin.',
  'distressed.how.footer': 'Template escrow only. Educational intelligence — not legal, tax, or investment advice. Conduct independent due diligence before committing capital.',
  'distressed.filtersTitle': 'Listings directory',
  'distressed.filtersSub': 'Filter by lane, region, and score — search programs and pathways',
