  'agents.eyebrow': 'LIAISON AGENTS',
  'agents.how.eyebrow': 'HOW THIS WORKS',
  'agents.how.title': 'Why Agents exist — and how Nexus coordinates your stack',
  'agents.how.intro': 'Agents is MotoPass’s Nexus pillar — the club layer where sovereign operators connect via Nostr, get country-specific guidance, and escalate from research to stamped application without email or brochure gatekeepers.',
  'agents.how.step1.title': 'Connect your npub',
  'agents.how.step1.body': 'MotoPass is Nostr-native. Connect your browser extension (Alby, nos2x, etc.) and your public key becomes your identity across Apply, Agents, and future club relays — no email signup.',
  'agents.how.step2.title': 'Kimi orchestrates, country agents advise',
  'agents.how.step2.body': 'Kimi is your strategic liaison on M4 HERMES — she routes you to jurisdiction-specific agents (Uruguay, El Salvador, UAE, and more) trained on flagship program data and Satohash proof requirements.',
  'agents.how.step3.title': 'Message with proof context',
  'agents.how.step3.body': 'Each agent card opens a Nostr DM stub (kind:14) pre-filled with program context. Pair with Vault verification and Distressed listings so every conversation references independently verifiable claims.',
  'agents.how.step4.title': 'Escalate from interest to application',
  'agents.how.step4.body': 'Register interest at Apply (launch-gated), stamp your application hash on Bitcoin, then loop back here to coordinate document prep, pathway optimization, and counsel hand-offs via Nostr.',
  'agents.how.footer': 'Agent guidance is educational intelligence — not legal, tax, immigration, or investment advice. Verify every claim on Bitcoin before committing capital.',
  'agents.nexus.title': 'Elite Sovereign Nexus',
  'agents.nexus.sub': 'Nostr identity · Kimi orchestration · BTC/Lightning rails · club coordination without velvet rope',
  'agents.paige.title': 'Paige AI concierge',
  'agents.paige.body': 'Ask jurisdiction questions grounded in countries.json. Paige cites Satohash proof IDs when available and flags unverified fields honestly. Escalates to Kimi or country agents when human judgment is needed.',
  'agents.dealroom.title': 'Deal room escalation',
  'agents.dealroom.body': 'From Distressed listings, open a deal room thread to escalate to Kimi with proof context, escrow template notes, and pathway red flags — MotoPass coordinates intelligence, never custody.',
  'agents.gridTitle': 'Country liaison agents (via Kimi)',
  'agents.connectHint': 'Connect Nostr — Kimi routes you to the right country agent',
  'agents.message': 'Message via Nostr',
  'agents.messageSoon': 'Coming soon',
  'agents.disclaimer': 'Liaison agents assist verified Nostr users with official passport office conversations. All agent guidance is informational — not legal advice. Stamped interactions anchor to Satohash.',
  'agents.statusActive': 'Active',
  'agents.statusBeta': 'Beta',
  'agents.statusComing': 'Coming',
  'agents.uy.region': 'South America',
  'agents.uy.focus': 'RBI territorial tax, crypto-friendly residency',
  'agents.sv.region': 'Central America',
