  'vault.doc.title': 'Sella tus propios documentos',
  'vault.doc.subtitle': 'Suelta cualquier archivo (escaneo de pasaporte, contrato, solicitud) — se hasea localmente y el SHA-256 se ancla en Bitcoin vía la API Satohash. El archivo en sí nunca sale de este dispositivo.',
