  'agents.disclaimer': 'Los agentes de enlace asisten a usuarios Nostr verificados en conversaciones con oficinas oficiales de pasaportes. Toda la orientación de agentes es informativa — no asesoramiento legal. Las interacciones selladas se anclan a Satohash.',
  'agents.how.eyebrow': 'CÓMO FUNCIONA',
  'agents.how.title': 'Por qué existen los Agentes — y cómo Nexus coordina tu stack',
  'agents.how.intro': 'Agentes es el pilar Nexus de MotoPass — la capa de club donde los operadores soberanos se conectan vía Nostr, reciben orientación por país y escalan de la investigación a la solicitud sellada sin guardianes de correo o folleto.',
  'agents.how.step1.title': 'Conecta tu npub',
  'agents.how.step1.body': 'MotoPass es nativo de Nostr. Conecta tu extensión de navegador (Alby, nos2x, etc.) y tu clave pública se convierte en tu identidad en Solicitar, Agentes y futuros relays del club — sin registro por correo.',
  'agents.how.step2.title': 'Kimi orquesta, los agentes del país aconsejan',
  'agents.how.step2.body': 'Kimi es tu enlace estratégico en M4 HERMES — te orienta a agentes específicos por jurisdicción (Uruguay, El Salvador, EAU, y más) entrenados en datos de programas insignia y requisitos de prueba Satohash.',
  'agents.how.step3.title': 'Mensaje con contexto de prueba',
  'agents.how.step3.body': 'Cada tarjeta de agente abre un stub de DM Nostr (kind:14) pre-llenado con el contexto del programa. Combínalo con la verificación de la Bóveda y los listados Distressed para que cada conversación referencie datos verificables de forma independiente.',
  'agents.how.step4.title': 'Escala del interés a la solicitud',
  'agents.how.step4.body': 'Registra tu interés en Solicitar (bloqueado al lanzamiento), sella tu hash de solicitud en Bitcoin, y luego vuelve aquí para coordinar la preparación de documentos, la optimización de vía y los traspasos de consejo vía Nostr.',
  'agents.how.footer': 'La orientación del agente es inteligencia educativa — no asesoramiento legal, fiscal, migratorio ni de inversión. Verifica cada dato en Bitcoin antes de comprometer capital.',
