  'vault.educationEyebrow': 'Éducation du Coffre',
  'vault.educationTitle': 'Comment fonctionnent les preuves OpenTimestamps',
  'vault.educationBody': 'Brève démonstration du hachage des données de programme, du téléversement des reçus .ots et de la confirmation des ancres sur Bitcoin — la vidéo arrive dans un futur BUILD.',
  'vault.educationStub': 'Voir la démonstration (bientôt)',
  'vault.educationStubHint': 'Emplacement vidéo — stub de démonstration caméra',
  'vault.doc.title': 'Scellez vos propres documents',
  'vault.doc.subtitle': 'Déposez n\'importe quel fichier (scan de passeport, contrat, candidature) — il est haché localement et le SHA-256 est ancré sur Bitcoin via l\'API Satohash. Le fichier lui-même ne quitte jamais cet appareil.',
  'vault.doc.pick': 'Choisissez des documents à sceller',
  'vault.doc.dropTitle': 'Déposez un fichier ici (ou cliquez pour parcourir)',
  'vault.doc.dropDescription': 'Le hachage reste local — seul le SHA-256 est envoyé à Satohash',
  'vault.doc.stamping': 'Hachage et scellement',
  'vault.doc.refresh': 'Revérifier le statut d\'ancrage',
  'vault.doc.copyHash': 'Copier le hachage de contenu',
  'vault.doc.verify': 'Vérifier sur Satohash',
  'vault.doc.delete': 'Retirer du registre',
  'vault.doc.status.pending': 'En attente',
  'vault.doc.status.confirmed': 'Confirmé',
  'vault.doc.status.error': 'Erreur',
  'vault.doc.confirmedBlock': 'Bloc {block}',
  'vault.doc.privacyNote': 'Les fichiers ne sont jamais téléversés ni stockés — seul le hachage est scellé. Un sceau confirmé prouve que ce fichier exact existait à ce bloc Bitcoin. Ce registre est stocké uniquement sur cet appareil.',
  'vault.lineageTitle': 'Lignée de preuve',
  'vault.expandLineage': 'Lignée',
  'vault.collapseLineage': 'Masquer la lignée',
  'vault.nostrPublish': 'Annoncer sur Nostr',
  'vault.blockLabel': 'Bloc',
  'vault.hashLabel': 'Hachage de contenu',
  'vault.otsLabel': 'Reçu OTS',
  'vault.tip.badgeVerified': 'Vérifié sur Bitcoin — Satohash confirme que cette ancre se trouve dans un bloc Bitcoin. L\'état de preuve le plus fort.',
  'vault.tip.badgeRecorded': 'Preuve enregistrée — le hachage et le bloc sont consignés ici. Confirmez sur Satohash pour l\'ancrage on-chain final.',
  'vault.tip.badgePending': 'Ancrage en attente — soumis au service d\'horodatage, en attente d\'un bloc Bitcoin.',
  'vault.tip.badgeDemo': 'Ancre de démo — un emplacement issu des données de semence. Pas encore scellé sur Bitcoin.',
  'vault.tip.block': 'Le bloc Bitcoin dans lequel cette preuve est ancrée — un horodatage permanent et public que n\'importe qui peut vérifier.',
  'vault.tip.checked': 'La dernière fois que ce programme a été revu.',
  'vault.tip.hash': 'Empreinte SHA-256 des données ancrées — elle prouve que ce contenu exact existait à ce bloc.',
  'vault.tip.ots': 'Reçu OpenTimestamps (.ots). Téléchargez-le pour vérifier de manière indépendante — sans compte ni service.',
  'vault.tip.useProof': 'Joignez ce hachage de preuve à une candidature de passeport comme élément de preuve.',
  'vault.tip.copyUrl': 'Copiez le lien de vérification Satohash pour le partager ou l\'enregistrer.',
  'vault.tip.satohash': 'Ouvrez Satohash.io pour vérifier cette preuve sur Bitcoin.',
  'vault.tip.otsDownload': 'Téléchargez le reçu OpenTimestamps pour une vérification hors ligne.',
  'vault.tip.apply': 'Démarrez une candidature pour ce programme avec sa preuve pré-jointe.',
  'vault.tip.nostr': 'Publiez une annonce d\'horodatage signée vers vos relays Nostr. Nostr est un commérage — la preuve OTS/Satohash est l\'élément de preuve.',
  'vault.tip.lineage': 'Chaque preuve enregistrée pour ce programme — voyez comment l\'ancre a évolué dans le temps.',
  'vault.tip.lineageEventId': 'Copiez l\'ID d\'événement Nostr — votre annonce de preuve signée. Conservez-le pour référencer l\'événement plus tard.',
  'vault.how.eyebrow': 'COMMENT CELA FONCTIONNE',
  'vault.how.title': 'Pourquoi le Coffre existe — et comment l\'utiliser',
  'vault.how.intro': 'Le Coffre est le pilier Seal de MotoPass. Chaque donnée matérielle de programme devrait porter un acte de naissance Bitcoin. Cette page vous permet d\'auditer ces preuves vous-même — aucune confiance de brochure requise.',
  'vault.how.step1.title': 'Ce qui est scellé',
  'vault.how.step1.body': 'Les instantanés de programmes fleurons — coûts, extraits légaux, notes de parcours — sont hachés et ancrés sur Bitcoin via OpenTimestamps. Satohash.io fournit des reçus de vérification lisibles avec hauteur de bloc.',
  'vault.how.step2.title': 'Ancres vérifiées vs démo',
  'vault.how.step2.body': 'Les preuves vérifiées ont de vraies URL Satohash et des fichiers .ots facultatifs sur disque. Les ancres de démo sont des emplacements de semence — utiles pour tester l\'UI mais pas une preuve de chaîne indépendante. Les puces de filtre permettent de voir chaque voie clairement.',
  'vault.how.step3.title': 'Vérifiez dans votre navigateur',
  'vault.how.step3.body': 'Collez un hachage de contenu SHA-256, téléversez un fichier .ots correspondant, ou cliquez sur « Utiliser cette preuve » sur n\'importe quelle carte de programme. MotoPass valide le format localement et vous renvoie à Satohash pour la vérification indépendante.',
  'vault.how.step4.title': 'Partagez la lignée de preuve',
  'vault.how.step4.body': 'Copiez un stub d\'événement Nostr kind:30078 pour diffuser les mises à jour de programme sur votre relay. Associez-le à Postuler pour sceller votre propre hachage de candidature — le même pipeline que les opérateurs utilisent pour la diligence.',
  'vault.how.footer': 'Pédagogique uniquement — pas un conseil juridique, fiscal ou d\'investissement. MotoPass ne garde pas vos documents ; vous vérifiez indépendamment sur Bitcoin.',
  'distressed.how.eyebrow': 'COMMENT CELA FONCTIONNE',
  'distressed.how.title': 'Pourquoi Distressed existe — et comment circulent les offres',
  'distressed.how.intro': 'Distressed est le pilier Forge de MotoPass — un marché verrouillé par preuve pour les coups souverains sous-évalués, économes en capital ou structurellement intéressants. Pas un site d\'annonces. Chaque ligne exige une preuve Satohash avant d\'apparaître.',
  'distressed.how.step1.title': 'Comment les annonces sont construites',
  'distressed.how.step1.body': 'Seuls les programmes à profondeur fleuron avec parcours et preuves Satohash sont admissibles. Chaque annonce montre un parcours, une demande en ₿ d\'abord, des drapeaux rouges et des conseils d\'optimisation tirés des données en direct de countries.json — pas un texte marketing statique.',
  'distressed.how.step2.title': 'Organisé vs sans permission',
  'distressed.how.step2.body': 'Voie organisée : les coups les mieux notés sélectionnés par Kimi pour l\'adéquation opérateur. Voie sans permission : même porte de preuve, mais l\'acheteur doit être prudent — MotoPass coordonne l\'intelligence, pas la garde. Les deux voies exigent proof_url.',
  'distressed.how.step3.title': 'Lire le score distressed',
  'distressed.how.step3.body': 'Le score de 1 à 5 classe l\'efficacité du capital et les signaux de valeur — minimums plus bas, routes de solvabilité, mots-clés budgétaires et arbitrages de souveraineté. Filtrez par région, score min. et demande max. pour resserrer vos candidats de stack.',
  'distressed.how.step4.title': 'De l\'annonce à la salle de deal',
  'distressed.how.step4.body': 'Ouvrez une carte → vérifiez la preuve dans le Coffre → examinez le modèle d\'escrow (stub PSBT, sans garde de fonds) → Postulez ou escaladez à un agent Kimi dans la salle de deal. MotoPass ne détient jamais votre Bitcoin.',
  'distressed.how.footer': 'Escrow modèle uniquement. Intelligence pédagogique — pas un conseil juridique, fiscal ou d\'investissement. Menez votre propre diligence avant d\'engager du capital.',
  'distressed.filtersTitle': 'Répertoire des annonces',
