  'vault.doc.title': 'Sele os seus próprios documentos',
  'vault.doc.subtitle': 'Solte qualquer ficheiro (scan de passaporte, contrato, candidatura) — é hasheado localmente e o SHA-256 é ancorado em Bitcoin via API Satohash. O ficheiro em si nunca sai deste dispositivo.',
