  'vault.doc.status.error': 'Erro',
  'vault.doc.confirmedBlock': 'Bloco {block}',
  'vault.doc.privacyNote': 'Os ficheiros nunca são carregados ou armazenados — apenas o hash é selado. Um selo confirmado prova que este ficheiro exato existia nesse bloco Bitcoin. Este registo é armazenado apenas neste dispositivo.',
  'vault.lineageTitle': 'Linhagem da prova',
