  'vault.tip.hash': 'Impressão digital SHA-256 dos dados ancorados — prova que este conteúdo exato existia nesse bloco.',
  'vault.tip.ots': 'Recibo OpenTimestamps (.ots). Descarregue-o para verificar de forma independente — sem conta ou serviço.',
  'vault.tip.useProof': 'Anexe este hash de prova a uma candidatura de passaporte como evidência.',
  'vault.tip.copyUrl': 'Copie o link de verificação Satohash para partilhar ou guardar.',
  'vault.tip.satohash': 'Abra Satohash.io para verificar esta prova em Bitcoin.',
  'vault.tip.otsDownload': 'Descarregue o recibo OpenTimestamps para verificação offline.',
  'vault.tip.apply': 'Inicie uma candidatura para este programa com a sua prova pré-anexada.',
  'vault.tip.nostr': 'Publique um anúncio de carimbo de tempo assinado nos seus relays Nostr. Nostr é boato — a prova OTS/Satohash é a evidência.',
  'vault.tip.lineage': 'Cada prova registada para este programa — veja como a âncora evoluiu ao longo do tempo.',
  'vault.tip.lineageEventId': 'Copie o ID do evento Nostr — o seu anúncio de prova assinado. Guarde-o para referenciar o evento mais tarde.',
  'vault.how.eyebrow': 'COMO FUNCIONA',
  'vault.how.title': 'Porque existe o Cofre — e como usá-lo',
  'vault.how.intro': 'O Cofre é o pilar Seal do MotoPass. Cada alegação material de programa deveria carregar um certificado de nascimento Bitcoin. Esta página permite-lhe auditar essas provas você mesmo — sem confiança de brochura.',
  'vault.how.step1.title': 'O que é selado',
  'vault.how.step1.body': 'Instantâneos de programas emblemáticos — custos, extratos legais, notas de via — são hasheados e ancorados em Bitcoin via OpenTimestamps. O Satohash.io fornece recibos de verificação legíveis com altura de bloco.',
  'vault.how.step2.title': 'Âncoras verificadas vs demo',
  'vault.how.step2.body': 'Provas verificadas têm URLs Satohash reais e ficheiros .ots opcionais em disco. Âncoras demo são espaços reservados de semeadura — úteis para testar a UI, mas não prova de cadeia independente. Os chips de filtro permitem ver cada via claramente.',
  'vault.how.step3.title': 'Verifique no seu navegador',
  'vault.how.step3.body': 'Cole um hash de conteúdo SHA-256, carregue um ficheiro .ots correspondente, ou clique em «Usar esta prova» em qualquer cartão de programa. O MotoPass valida o formato localmente e liga-o ao Satohash para verificação independente.',
  'vault.how.step4.title': 'Partilhe a linhagem da prova',
  'vault.how.step4.body': 'Copie um stub de evento Nostr kind:30078 para transmitir atualizações de programa no seu relay. Combine com Candidatar-se para selar o seu próprio hash de candidatura — a mesma pipeline que os operadores usam para diligência.',
  'vault.how.footer': 'Apenas educativo — não é aconselhamento jurídico, fiscal ou de investimento. O MotoPass não guarda documentos; verifique de forma independente em Bitcoin.',
  'distressed.how.eyebrow': 'COMO FUNCIONA',
  'distressed.how.title': 'Porque existe o Distressed — e como fluem os negócios',
  'distressed.how.intro': 'Distressed é o pilar Forge do MotoPass — um mercado bloqueado por prova para jogadas soberanas subvalorizadas, eficientes em capital ou estruturalmente interessantes. Não é um site de listagens. Cada linha exige prova Satohash antes de aparecer.',
  'distressed.how.step1.title': 'Como as listagens são construídas',
  'distressed.how.step1.body': 'Apenas programas com profundidade emblemática, vias e provas Satohash qualificam. Cada listagem mostra uma via, um pedido em ₿ primeiro, bandeiras vermelhas e dicas de otimização tiradas de countries.json ao vivo — não texto de marketing estático.',
  'distressed.how.step2.title': 'Selecionado vs sem permissão',
  'distressed.how.step2.body': 'Via selecionada: jogadas com melhor pontuação escolhidas pela Kimi para adequação ao operador. Via sem permissão: mesma porta de prova, mas comprador cuidado — o MotoPass coordena inteligência, não custódia. Ambas as vias exigem proof_url.',
  'distressed.how.step3.title': 'Ler a pontuação distressed',
  'distressed.how.step3.body': 'A pontuação de 1 a 5 classifica eficiência de capital e sinais de valor — mínimos mais baixos, rotas de solvência, palavras-chave orçamentais e compromissos de soberania. Filtre por região, pontuação mín. e pedido máx. para restringir os seus candidatos de stack.',
  'distressed.how.step4.title': 'Da listagem à sala de negócios',
  'distressed.how.step4.body': 'Abra um cartão → verifique a prova no Cofre → reveja o modelo de escrow (stub PSBT, sem custódia de fundos) → Candidatar-se ou escalar para um agente Kimi na sala. O MotoPass nunca detém o seu Bitcoin.',
  'distressed.how.footer': 'Apenas escrow de modelo. Inteligência educativa — não aconselhamento jurídico, fiscal ou de investimento. Faça diligência independente antes de comprometer capital.',
  'distressed.filtersTitle': 'Diretório de listagens',
  'distressed.filtersSub': 'Filtre por via, região e pontuação — pesquise programas e vias',
