  'nav.shortcuts.footerGap': 'Espaço de rodapé? A folga móvel vive apenas em footer-glass — sem preenchimento de shell de layout abaixo do main.',
  'agents.eyebrow': 'AGENTES DE LIGAÇÃO',
  'agents.gridTitle': 'Agentes de ligação por país (via Kimi)',
  'agents.connectHint': 'Ligue Nostr — a Kimi orienta-o para o agente do país certo',
  'agents.message': 'Mensagem via Nostr',
  'agents.messageSoon': 'Em breve',
  'agents.disclaimer': 'Agentes de ligação assistem utilizadores Nostr verificados em conversas com gabinetes oficiais de passaportes. Todas as orientações de agentes são informativas — não aconselhamento jurídico. Interações seladas ancoram-se no Satohash.',
  'agents.how.eyebrow': 'COMO FUNCIONA',
  'agents.how.title': 'Porque existem os Agentes — e como o Nexus coordena o seu stack',
  'agents.how.intro': 'Agents é o pilar Nexus do MotoPass — a camada de clube onde operadores soberanos se ligam via Nostr, obtêm orientação por país e escalam de pesquisa para candidatura selada sem guardiões de e-mail ou brochura.',
  'agents.how.step1.title': 'Ligue o seu npub',
  'agents.how.step1.body': 'O MotoPass é nativo Nostr. Ligue a sua extensão de navegador (Alby, nos2x, etc.) e a sua chave pública torna-se a sua identidade em Candidatar-se, Agents e futuros relays de clube — sem registo por e-mail.',
  'agents.how.step2.title': 'Kimi orquestra, agentes do país aconselham',
  'agents.how.step2.body': 'A Kimi é a sua ligação estratégica no M4 HERMES — orienta-o para agentes específicos por jurisdição (Uruguai, El Salvador, EAU, e mais) treinados em dados de programas emblemáticos e requisitos de prova Satohash.',
  'agents.how.step3.title': 'Mensagem com contexto de prova',
  'agents.how.step3.body': 'Cada cartão de agente abre um stub de DM Nostr (kind:14) pré-preenchido com contexto do programa. Combine com a verificação do Cofre e listagens Distressed para que cada conversa referencie alegações verificáveis de forma independente.',
  'agents.how.step4.title': 'Escale do interesse à candidatura',
