  'pitch.ctaBand.vault': '探索金库',
  'pitch.faq.q1': '什么是MotoPass？',
  'pitch.faq.a1': 'MotoPass是一个比特币原生平台，用于评估、比较和叠加主权居留与公民身份项目，配有Satohash验证的数据和Nostr身份。',
  'pitch.faq.q2': 'Satohash验证如何运作？',
  'pitch.faq.a2': '实质性声明会被哈希并通过OpenTimestamps锚定到比特币。任何人都可以在Satohash.io上独立验证证明，而无需信任宣传册快照。',
  'pitch.faq.q3': '申请需要邮箱吗？',
  'pitch.faq.a3': '不需要。MotoPass使用Nostr npub原生注册——连接你的浏览器扩展，你的公钥就成为你的账户。',
  'pitch.faq.q4': '金库有什么用？',
  'pitch.faq.a4': '金库是你审计Satohash证明的地方——粘贴内容哈希、上传OpenTimestamps文件或选择项目并在比特币上验证锚定，无需相信MotoPass的一面之词。',
  'pitch.faq.q5': '什么是Distressed？',
  'pitch.faq.a5': 'Distressed是一个资本高效主权交易的证明门槛市场。列表要求Satohash证明、先显示₿出价，并提供模板托管和Kimi代理升级——MotoPass绝不托管资金。',
  'pitch.guide.eyebrow': '了解MotoPass',
  'pitch.guide.title': '一个平台、四大支柱、零宣传册信任',
  'pitch.guide.intro': 'MotoPass是主权运营者的私有操作系统——研究司法辖区、在比特币上验证声明、跟踪组合并通过Nostr协调。这是从左到右的完整旅程。',
  'pitch.guide.step1.title': 'Forge——发现与建模',
  'pitch.guide.step1.body': '从项目开始：筛选50个司法辖区、运行组合模拟器、比较费用并检查BTC地图商户密度。当你想走资本高效路线时，Distressed会呈现证明门槛的价值交易。',
  'pitch.guide.step2.title': 'Seal——在比特币上验证',
  'pitch.guide.step2.body': '每项实质性声明都应锚定到比特币区块。金库让你粘贴哈希、上传.ots文件并通过Satohash.io独立审计证明——可验证的真相。',
  'pitch.guide.step3.title': 'Ledger——跟踪你的组合',
  'pitch.guide.step3.body': '将已获取的项目保存到投资组合、建模多辖区组合并从实时项目数据监控主权评分、Lightning就绪度和续签时间线。',
  'pitch.guide.step4.title': 'Nexus——申请与协调',
  'pitch.guide.step4.body': '连接你的npub、在申请页登记意向（启动门槛控制）、给申请哈希盖章并升级到Kimi联络代理——无需邮箱、无需Salesforce、无需天鹅绒绳。',
  'pitch.guide.footer': '仅为教育性情报——非法律、税务、移民或投资建议。投入资金前请独立验证每一项声明。',
