  'agents.how.step2.body': 'Kimi هو جهة اتصالك الاستراتيجية على M4 HERMES — يوجّهك إلى وكلاء خاصين بكل اختصاص (أوروغواي والسلفادور والإمارات وغيرها) مدرّبين على بيانات البرامج الرائدة ومتطلبات إثبات Satohash.',
  'agents.how.step3.title': 'راسل بسياق الإثبات',
