  'nav.shortcuts.footerGap': 'Footer-Abstand? Mobile Clearance lebt nur auf footer-glass — kein Layout-Shell-Padding unterhalb des Mains.',
  'agents.eyebrow': 'VERBINDUNGSAGENTEN',
  'agents.gridTitle': 'Länder-Verbindungsagenten (via Kimi)',
  'agents.connectHint': 'Nostr verbinden — Kimi leitet dich zum richtigen Länder-Agenten',
  'agents.message': 'Nachricht via Nostr',
  'agents.messageSoon': 'Demnächst',
  'agents.disclaimer': 'Verbindungsagenten unterstützen verifizierte Nostr-Nutzer bei Gesprächen mit offiziellen Passbehörden. Alle Agenten-Hinweise sind informativ — keine Rechtsberatung. Gestempelte Interaktionen verankern sich auf Satohash.',
  'agents.how.eyebrow': 'SO FUNKTIONIERT ES',
  'agents.how.title': 'Warum die Agenten existieren — und wie Nexus deinen Stack koordiniert',
  'agents.how.intro': 'Agents ist das Nexus-Pillar von MotoPass — die Club-Ebene, auf der sich souveräne Betreiber über Nostr verbinden, länderspezifische Hinweise erhalten und von Forschung zu gestempelter Bewerbung aufsteigen — ohne E-Mail- oder Prospekt-Gatekeeper.',
  'agents.how.step1.title': 'Verbinde deinen npub',
  'agents.how.step1.body': 'MotoPass ist Nostr-nativ. Verbinde deine Browsererweiterung (Alby, nos2x usw.) und dein öffentlicher Schlüssel wird deine Identität in Bewerben, Agents und zukünftigen Club-Relays — keine E-Mail-Anmeldung.',
  'agents.how.step2.title': 'Kimi orchestriert, Länder-Agenten beraten',
  'agents.how.step2.body': 'Kimi ist deine strategische Verbindung auf M4 HERMES — sie leitet dich an jurisdiktionsspezifische Agenten weiter (Uruguay, El Salvador, VAE und mehr), die auf Flaggschiff-Programmdaten und Satohash-Beweisanforderungen trainiert sind.',
  'agents.how.step3.title': 'Mit Beweiskontext schreiben',
  'agents.how.step3.body': 'Jede Agenten-Karte öffnet einen Nostr-DM-Stub (kind:14), vorbefüllt mit Programmkontext. Kombiniere ihn mit der Tresor-Prüfung und Distressed-Listings, damit sich jedes Gespräch auf unabhängig prüfbare Behauptungen bezieht.',
  'agents.how.step4.title': 'Vom Interesse zur Bewerbung eskalieren',
  'agents.how.step4.body': 'Registriere Interesse bei Bewerben (launch-gated), stemple deinen Bewerbungshash auf Bitcoin und komm dann hierher zurück, um Dokumentenvorbereitung, Weg-Optimierung und Beratungs-Übergaben über Nostr zu koordinieren.',
  'agents.how.footer': 'Agenten-Hinweise sind Bildungs-Intelligenz — keine Rechts-, Steuer-, Einwanderungs- oder Anlageberatung. Prüfe jede Behauptung auf Bitcoin, bevor du Kapital bindest.',
  'agents.nexus.title': 'Elite Sovereign Nexus',
  'agents.nexus.sub': 'Nostr-Identität · Kimi-Orchestrierung · BTC/Lightning-Schienen · Club-Koordination ohne Samtseil',
  'agents.paige.title': 'Paige KI-Concierge',
  'agents.paige.body': 'Stelle Jurisdiktionsfragen, die auf countries.json basieren. Paige zitiert Satohash-Beweis-IDs, wenn verfügbar, und markiert unverifizierte Felder ehrlich. Sie eskaliert an Kimi oder Länder-Agenten, wenn menschliches Urteil nötig ist.',
  'agents.dealroom.title': 'Deal-Room-Eskalation',
  'agents.dealroom.body': 'Öffne aus Distressed-Listings einen Deal-Room-Thread, um mit Beweiskontext, Escrow-Vorlagen-Notizen und Weg-Rotflaggen an Kimi zu eskalieren — MotoPass koordiniert Intelligenz, niemals Verwahrung.',
