  'vault.verify.resultsExplainerOk': 'Sieht lokal gut aus — das Hash-Format ist gültig oder deine .ots-Datei wurde geladen. Öffne Satohash, um zu bestätigen, dass der Beweis auf Bitcoin verankert ist; MotoPass ersetzt keine unabhängige Verifizierung.',
